script:
const text = `${ctx.testPrefix} ${ctx.params.van_de || 'Phiếu tự động'}`;
const dlg = page.locator('[role=dialog]');

await step('Mở form Tạo phiếu', async () => {
  await page.waitForLoadState('networkidle', { timeout: 20000 }).catch(() => {});
  await page.getByRole('button', { name: 'Tạo phiếu' }).click();
  await dlg.waitFor({ timeout: 10000 });
});

await step('Nhập vấn đề gặp phải', async () => {
  const ta = dlg.locator('textarea[placeholder="Nhập vấn đề gặp phải"]');
  await ta.click();
  await ta.pressSequentially(text);
});

await step('Đính kèm hình mô tả (nếu có)', async () => {
  if (!(await attachFiles(dlg.locator('input[type=file]').first(), 'anh_mo_ta'))) { ctx.log('Không có hình mô tả, bỏ qua'); return; }
  await page.waitForTimeout(2000);
});

await step('Chọn ngày và giờ', async () => {
  // Lịch có hai nửa (bắt đầu và kết thúc) nên danh sách giờ xuất hiện hai lần; chỉ nửa kết thúc hiện ra.
  const label = dlg.locator('.rc-input-calendar__label').first();
  await label.click();
  const days = page.locator('.DayPicker-Day:not(.DayPicker-Day--outside)');
  await days.first().waitFor({ state: 'visible', timeout: 8000 }).catch(async () => {
    await label.dispatchEvent('click');
    await days.first().waitFor({ state: 'visible', timeout: 8000 });
  });
  // Ngày = hôm nay cộng ngay_them ngày; qua cuối tháng thì lấy ngày cuối tháng (lịch chỉ hiện tháng này)
  const now = new Date();
  const last = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const offset = Math.max(parseInt(ctx.params.ngay_them || '1', 10) || 0, 0);
  const day = Math.min(now.getDate() + offset, last);
  await days.filter({ hasText: new RegExp('^' + day + '$') }).first().click();
  await page.locator('.hrv-date-time-picker-end-day input.hrv-date-time-picker-input-time').click();
  await pickOption(page.locator('.hrv-date-time-picker-end-day .hrv-date-time-picker-input-menu-item'), 'gio');
  await dlg.getByText('Tạo phiếu', { exact: true }).first().click();
});

await step('Chọn phân loại, mức độ xử lý, đơn vị phát sinh', async () => {
  // Giá trị lấy từ tham số; không có trong danh mục của tài khoản này thì chọn mục đầu tiên (xem log)
  const opens = dlg.getByRole('button', { name: 'Open' });
  const items = page.locator('[role=listbox] li');
  await opens.nth(0).click();
  await pickOption(items, 'phan_loai');
  await opens.nth(1).click();
  await pickOption(items, 'muc_do_xu_ly');
  await opens.nth(2).click();
  await pickOption(items, 'don_vi');
});

await step('Bấm Tạo', async () => {
  const btn = dlg.locator('.hrw-button-primary:not(.hrw-button_disable)', { hasText: /^Tạo$/ });
  await btn.first().waitFor({ timeout: 10000 });
  await btn.first().click();
  await dlg.waitFor({ state: 'hidden', timeout: 15000 });
});

await step('Phiếu xuất hiện trong tab Tất cả', async () => {
  await page.getByText('Tất cả', { exact: true }).first().click();
  await page.getByText(text).first().waitFor({ timeout: 30000 });
});
ctx.log('Đã tạo phiếu: ' + text);
